// Golden example: confirm deleting an orbit. One optional choice with a hint, and one tick the person must give,
// which says what to do in words when it is missing. Spacing is token variables only.
import { useState, type FormEvent } from "react";
import { Button, Checkbox, Field } from "../index";

const MISSING = "Tick this box to confirm. Orbit 7 cannot be restored.";

export default function ConfirmDeleteOrbit() {
  const [understood, setUnderstood] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [deleted, setDeleted] = useState(false);

  function submit(event: FormEvent) {
    event.preventDefault();
    setError(understood ? null : MISSING);
    setDeleted(understood);
  }

  return (
    <form
      noValidate
      onSubmit={submit}
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--space-20)",
      }}
    >
      <Field.Root name="deleteCharts">
        <Field.Label>
          <Checkbox defaultChecked />
          Also delete its 12 charts
        </Field.Label>
        <Field.Description>
          Charts that other dashboards use are kept.
        </Field.Description>
      </Field.Root>
      <Field.Root name="understood" invalid={error !== null}>
        <Field.Label>
          <Checkbox
            required
            checked={understood}
            onCheckedChange={(checked) => {
              setUnderstood(checked);
              if (checked) setError(null);
              setDeleted(false);
            }}
          />
          I understand this cannot be undone
        </Field.Label>
        <Field.Error match={error !== null}>{error}</Field.Error>
      </Field.Root>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: "var(--space-12)",
        }}
      >
        <Button variant="primary" type="submit">
          Delete orbit
        </Button>
        <span role="status">{deleted ? "Orbit 7 deleted." : ""}</span>
      </div>
    </form>
  );
}

// Golden example: confirm before deleting an orbit. Deleting removes the row, and the trigger with it, so
// the popup passes finalFocus to the list heading instead of leaving focus on <body>. Spacing is token variables only.
import { useRef, useState } from "react";
import { Dialog } from "../index";

const ORBITS = [
  { id: "kepler", name: "Kepler", moons: 12 },
  { id: "vesta", name: "Vesta", moons: 3 },
];

export default function DeleteOrbit() {
  const [orbits, setOrbits] = useState(ORBITS);
  const heading = useRef<HTMLHeadingElement>(null);

  return (
    <section aria-labelledby="orbits-heading">
      <h2 id="orbits-heading" ref={heading} tabIndex={-1} style={{ margin: 0 }}>
        Orbits
      </h2>
      <ul
        style={{
          display: "flex",
          flexDirection: "column",
          gap: "var(--space-12)",
          margin: 0,
          padding: 0,
          listStyle: "none",
        }}
      >
        {orbits.map((orbit) => (
          <li
            key={orbit.id}
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              gap: "var(--space-16)",
            }}
          >
            <span>{orbit.name}</span>
            <Dialog.Root>
              <Dialog.Trigger
                variant="secondary"
                aria-label={`Delete ${orbit.name}`}
              >
                Delete
              </Dialog.Trigger>
              <Dialog.Popup finalFocus={heading}>
                <Dialog.Header>
                  <Dialog.Title>Delete {orbit.name}?</Dialog.Title>
                  <Dialog.CloseIcon />
                </Dialog.Header>
                <Dialog.Description>
                  Its {orbit.moons} moons and their notes go with it. This
                  cannot be undone.
                </Dialog.Description>
                <Dialog.Actions>
                  <Dialog.Close variant="secondary">Keep orbit</Dialog.Close>
                  <Dialog.Close
                    variant="primary"
                    onClick={() =>
                      setOrbits((all) => all.filter((o) => o.id !== orbit.id))
                    }
                  >
                    Delete orbit
                  </Dialog.Close>
                </Dialog.Actions>
              </Dialog.Popup>
            </Dialog.Root>
          </li>
        ))}
      </ul>
    </section>
  );
}

// Golden example: sign in with an emailed link. The workspace is read-only, the email field explains its
// format up front and says what to fix in words when the address is incomplete. Spacing is token variables only.
import { useState, type FormEvent } from "react";
import { Button, Field, Input } from "../index";

const check = (email: string) =>
  /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)
    ? null
    : "Add the part after the @, for example ada@orbit.dev.";

export default function SignInWithLink() {
  const [email, setEmail] = useState("ada@orbit");
  const [error, setError] = useState<string | null>(check("ada@orbit"));
  const [sent, setSent] = useState(false);

  function submit(event: FormEvent) {
    event.preventDefault();
    const problem = check(email);
    setError(problem);
    setSent(!problem);
  }

  return (
    <form
      noValidate
      onSubmit={submit}
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--space-20)",
      }}
    >
      <Field.Root name="workspace">
        <Field.Label>Workspace</Field.Label>
        <Input readOnly value="orbit-lab" />
        <Field.Description>
          You were invited to this workspace.
        </Field.Description>
      </Field.Root>
      <Field.Root name="email" invalid={error !== null}>
        <Field.Label>Email</Field.Label>
        <Input
          type="email"
          autoComplete="email"
          value={email}
          onChange={(event) => {
            setEmail(event.target.value);
            setSent(false);
          }}
        />
        <Field.Description>
          We send a sign-in link to this address. No password needed.
        </Field.Description>
        <Field.Error match={error !== null}>{error}</Field.Error>
      </Field.Root>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: "var(--space-12)",
        }}
      >
        <Button variant="primary" type="submit">
          Send sign-in link
        </Button>
        <span role="status">{sent ? `Link sent to ${email}.` : ""}</span>
      </div>
    </form>
  );
}

